package com.prince.currencyexchange.exception; import com.prince.currencyexchange.dto.ErrorResponse; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(CurrencyNotFoundException.class) public ResponseEntity<ErrorResponse> currency(CurrencyNotFoundException ex,HttpServletRequest req){return build(HttpStatus.BAD_REQUEST,ex,req);} @ExceptionHandler(ExchangeRateNotFoundException.class) public ResponseEntity<ErrorResponse> rate(ExchangeRateNotFoundException ex,HttpServletRequest req){return build(HttpStatus.NOT_FOUND,ex,req);} private ResponseEntity<ErrorResponse> build(HttpStatus s,Exception ex,HttpServletRequest req){return ResponseEntity.status(s).body(new ErrorResponse(LocalDateTime.now(),s.value(),s.getReasonPhrase(),ex.getMessage(),req.getRequestURI()));}}